<?php
$u=sr_auth();$id=(int)$u['id'];
if($u['role']==='candidate'){
 $app=sr_count('SELECT COUNT(*) FROM applications WHERE candidate_id=?',[$id]);$short=sr_count("SELECT COUNT(*) FROM applications WHERE candidate_id=? AND status='shortlisted'",[$id]);
 $saved=sr_count('SELECT COUNT(*) FROM saved_jobs WHERE user_id=?',[$id]);$resume=sr_one('SELECT id,skills,updated_at FROM resumes WHERE user_id=?',[$id]);
 sr_page_heading('ỨNG VIÊN','Xin chào, '.$u['name'],'Hãy quản lý hành trình tìm việc và khám phá cơ hội phù hợp với bạn.');?>
 <div class="stats-grid"><div class="stat"><span>Đơn ứng tuyển</span><strong><?=$app?></strong><small>Đã gửi tới nhà tuyển dụng</small></div><div class="stat"><span>Vào danh sách chọn</span><strong><?=$short?></strong><small>Được quan tâm</small></div><div class="stat"><span>Công việc đã lưu</span><strong><?=$saved?></strong><small>Để xem lại sau</small></div><div class="stat"><span>Hồ sơ CV</span><strong><?=$resume?'01':'00'?></strong><small><?=$resume?'Đã sẵn sàng':'Chưa tải lên'?></small></div></div>
 <?php
 $cp=sr_one('SELECT headline,phone,location,education,experience FROM candidate_profiles WHERE user_id=?',[$id])?:[];
 $ready=[
  ['done'=>(bool)$resume,'label'=>'Tải CV và phân tích kỹ năng','url'=>'resume'],
  ['done'=>!empty($cp['headline'])&&!empty($cp['phone']),'label'=>'Hoàn thiện thông tin cá nhân','url'=>'profile'],
  ['done'=>$saved>0,'label'=>'Lưu công việc quan tâm','url'=>'home'],
  ['done'=>$app>0,'label'=>'Ứng tuyển công việc đầu tiên','url'=>'home']
 ];
 $completed=count(array_filter($ready,fn($i)=>$i['done']));$percent=(int)round($completed/count($ready)*100);
 ?>
 <section class="panel onboarding"><div class="onboard-copy"><span class="overline">LỘ TRÌNH CỦA BẠN</span><h2>Hồ sơ nghề nghiệp <?=$percent?>% sẵn sàng</h2><p>Hoàn thành các bước sau để tận dụng tốt hơn tính năng SmartRecruit.</p><div class="onboard-track"><span style="width:<?=$percent?>%"></span></div><small><?=$completed?>/<?=count($ready)?> bước đã hoàn thành</small></div><div class="onboard-steps"><?php foreach($ready as $step):?><a href="<?=sr_url($step['url'])?>" class="onboard-step <?=$step['done']?'done':''?>"><span><?=$step['done']?'✓':'○'?></span><?=h($step['label'])?><b>↗</b></a><?php endforeach;?></div></section>
 <div class="two-columns"><section class="panel"><div class="panel-top"><h2>Đơn ứng tuyển gần đây</h2><a class="text-link" href="<?=sr_url('applications')?>">Xem tất cả →</a></div><?php $apps=sr_all('SELECT a.*,j.title,j.company FROM applications a JOIN jobs j ON j.id=a.job_id WHERE a.candidate_id=? ORDER BY a.created_at DESC LIMIT 5',[$id]);if(!$apps):?><p class="muted">Bạn chưa ứng tuyển. Khám phá các vị trí đang tuyển ngay hôm nay.</p><a class="button secondary sm" href="<?=sr_url('home')?>">Tìm việc</a><?php else:?><?php foreach($apps as $a):?><div class="feed-row"><div><strong><?=h($a['title'])?></strong><small><?=h($a['company'])?> · <?=h(sr_date($a['created_at']))?></small></div><span class="badge <?=sr_state_class($a['status'])?>"><?=h(sr_status($a['status']))?></span></div><?php endforeach;?><?php endif;?></section><section class="panel"><div class="panel-top"><h2>Hồ sơ của bạn</h2><a class="text-link" href="<?=sr_url('profile')?>">Chỉnh sửa →</a></div><div class="profile-highlight"><div class="avatar large-avatar"><?=h(sr_initials($u['name']))?></div><div><strong><?=h($u['name'])?></strong><small><?=h(sr_one('SELECT email FROM users WHERE id=?',[$id])['email']??'')?></small></div></div><div class="divider"></div><?php if($resume):?><p class="muted">Kỹ năng AI đã phát hiện:</p><div class="skills"><?php foreach(array_slice(sr_skills($resume['skills']),0,9) as $skill):?><span><?=h($skill)?></span><?php endforeach;?></div><a class="button secondary sm top-gap" href="<?=sr_url('recommendations')?>">Xem gợi ý AI →</a><?php else:?><p>Hãy tải CV để nhận phân tích kỹ năng và gợi ý việc làm tự động.</p><a class="button primary sm" href="<?=sr_url('resume')?>">Tải CV ngay</a><?php endif;?></section></div>
 <?php
}elseif($u['role']==='recruiter'){
 $jobs=sr_count('SELECT COUNT(*) FROM jobs WHERE recruiter_id=?',[$id]);$approved=sr_count("SELECT COUNT(*) FROM jobs WHERE recruiter_id=? AND status='approved'",[$id]);
 $apps=sr_count('SELECT COUNT(*) FROM applications a JOIN jobs j ON j.id=a.job_id WHERE j.recruiter_id=?',[$id]);
 $selected=sr_count("SELECT COUNT(*) FROM applications a JOIN jobs j ON j.id=a.job_id WHERE j.recruiter_id=? AND a.status='shortlisted'",[$id]);
 sr_page_heading('NHÀ TUYỂN DỤNG','Tổng quan tuyển dụng','Nắm bắt các vị trí tuyển dụng và tình trạng ứng viên trong một màn hình.'); ?>
 <div class="stats-grid"><div class="stat"><span>Tin đã tạo</span><strong><?=$jobs?></strong><small>Tổng tất cả trạng thái</small></div><div class="stat"><span>Đang hiển thị</span><strong><?=$approved?></strong><small>Đã được duyệt</small></div><div class="stat"><span>Hồ sơ ứng tuyển</span><strong><?=$apps?></strong><small>Từ các vị trí của bạn</small></div><div class="stat"><span>Ứng viên tiềm năng</span><strong><?=$selected?></strong><small>Danh sách rút gọn</small></div></div>
 <div class="section-title"><div><h2>Tin tuyển dụng gần đây</h2></div><a class="button primary sm" href="<?=sr_url('job_form')?>">+ Đăng tin mới</a></div><div class="panel table-panel"><div class="table-responsive"><table><thead><tr><th>Vị trí</th><th>Ứng viên</th><th>Trạng thái</th><th>Thao tác</th></tr></thead><tbody><?php $items=sr_all('SELECT j.*, (SELECT COUNT(*) FROM applications a WHERE a.job_id=j.id) applications_count FROM jobs j WHERE j.recruiter_id=? ORDER BY j.id DESC LIMIT 8',[$id]);foreach($items as $j):?><tr><td><strong><?=h($j['title'])?></strong><small><?=h($j['company'])?></small></td><td><?=$j['applications_count']?></td><td><span class="badge <?=sr_state_class($j['status'])?>"><?=h(sr_status($j['status']))?></span></td><td><a href="<?=sr_url('job_form',['id'=>$j['id']])?>">Chỉnh sửa</a></td></tr><?php endforeach;?><?php if(!$items):?><tr><td colspan="4">Chưa có tin tuyển dụng nào.</td></tr><?php endif;?></tbody></table></div></div>
 <?php
}else{
 $users=sr_count('SELECT COUNT(*) FROM users');$jobs=sr_count('SELECT COUNT(*) FROM jobs');$pending=sr_count("SELECT COUNT(*) FROM jobs WHERE status='pending'");$apps=sr_count('SELECT COUNT(*) FROM applications');
 sr_page_heading('QUẢN TRỊ VIÊN','Tổng quan hệ thống','Theo dõi các chỉ số quan trọng của nền tảng SmartRecruit AI.'); ?>
 <div class="stats-grid"><div class="stat"><span>Tài khoản</span><strong><?=$users?></strong><small>Người dùng đã đăng ký</small></div><div class="stat"><span>Tổng tin tuyển dụng</span><strong><?=$jobs?></strong><small>Tất cả trạng thái</small></div><div class="stat"><span>Tin chờ phê duyệt</span><strong><?=$pending?></strong><small>Cần kiểm tra</small></div><div class="stat"><span>Đơn ứng tuyển</span><strong><?=$apps?></strong><small>Tất cả hồ sơ đã gửi</small></div></div>
 <div class="two-columns"><div class="panel"><h2>Quản lý nội dung</h2><p class="muted">Xét duyệt tin tuyển dụng và đảm bảo thông tin trên nền tảng phù hợp.</p><a class="button primary sm" href="<?=sr_url('admin_jobs')?>">Xem tin chờ duyệt →</a></div><div class="panel"><h2>Quản lý tài khoản</h2><p class="muted">Theo dõi người dùng và tạm khóa tài khoản vi phạm khi cần.</p><a class="button secondary sm" href="<?=sr_url('admin_users')?>">Quản lý người dùng →</a></div></div>
